sealed class MemoryRepository:IRepository {public State State=new();public bool Fail;public State Load()=>J.Clone(State);public void Save(State state){if(Fail)throw new IOException();State=J.Clone(state);}public void Dispose(){}}
sealed class MemoryAssets:IAttachments {readonly Dictionary<string,byte[]> bytes=[];public ImageAsset Persist(byte[] png,SourceInfo source,byte[]? thumbnail=null){var asset=new ImageAsset{Source=source,Width=1,Height=1,ByteLength=png.Length,Sha256=Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(png)).ToLowerInvariant()};bytes[asset.Id]=png;return asset;}public byte[] Read(ImageAsset asset,bool thumbnail=false)=>bytes[asset.Id];public void Delete(ImageAsset asset)=>bytes.Remove(asset.Id);public void Collect(IReadOnlySet<string> live){foreach(var id in bytes.Keys.Where(id=>!live.Contains(id)).ToArray())bytes.Remove(id);}}
sealed class FakeTransport:ITransport {public bool MissingKey,Slow,Fail,Checking;public int Starts;public string? Body;public string Answer="缓存保存结果。";public TaskCompletionSource? Preflight;public async Task EnsureCredentialsAsync(CancellationToken cancel){Checking=true;if(Preflight is not null)await Preflight.Task.WaitAsync(cancel);if(MissingKey)throw new AppFault("CREDENTIAL_REQUIRED","请填写Key");}public async IAsyncEnumerable<StreamDelta> StreamAsync(byte[] body,[EnumeratorCancellation]CancellationToken cancel){Starts++;Body=Encoding.UTF8.GetString(body);if(Slow)await Task.Delay(160,cancel);yield return new(Answer);await Task.Delay(5,cancel);if(Fail)throw new AppFault("NETWORK_ERROR","模拟断流",true);yield return new(FinishReason:"stop");}}
sealed class FakeVault:ICredentialVault {public string? Key="placeholder-api-key";public string? Read()=>Key;public void Save(string key)=>Key=key;public void Clear()=>Key=null;}
sealed class StubHandler(Func<HttpResponseMessage> response):HttpMessageHandler {public int Calls;protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken cancel){Calls++;return Task.FromResult(response());}}
sealed class OneByteStream(byte[] bytes):MemoryStream(bytes) {public override ValueTask<int> ReadAsync(Memory<byte> buffer,CancellationToken cancel=default)=>base.ReadAsync(buffer[..Math.Min(1,buffer.Length)],cancel);}
static class Png {public static byte[] Padded(int size){var original=Make();using var result=new MemoryStream();result.Write(original.AsSpan(0,original.Length-12));Chunk(result,"zzZZ",new byte[size-original.Length-12]);result.Write(original.AsSpan(original.Length-12));return result.ToArray();}public static byte[] Make(){using var data=new MemoryStream();data.Write([137,80,78,71,13,10,26,10]);var header=new byte[13];BinaryPrimitives.WriteInt32BigEndian(header,1);BinaryPrimitives.WriteInt32BigEndian(header.AsSpan(4),1);header[8]=8;header[9]=6;Chunk(data,"IHDR",header);using var compressed=new MemoryStream();using(var z=new ZLibStream(compressed,CompressionLevel.Fastest,true))z.Write([0,255,255,255,255]);Chunk(data,"IDAT",compressed.ToArray());Chunk(data,"IEND",[]);return data.ToArray();}static void Chunk(Stream output,string kind,byte[] body){Span<byte> size=stackalloc byte[4];BinaryPrimitives.WriteInt32BigEndian(size,body.Length);output.Write(size);var bytes=Encoding.ASCII.GetBytes(kind).Concat(body).ToArray();output.Write(bytes);uint crc=uint.MaxValue;foreach(var b in bytes){crc^=b;for(var i=0;i<8;i++)crc=(crc&1)!=0?(crc>>1)^0xedb88320:crc>>1;}BinaryPrimitives.WriteUInt32BigEndian(size,~crc);output.Write(size);}}
